const DISCLAIMER='Alat bantu observasi dan pemetaan awal. Bukan alat diagnosis psikologis.';
const LONG_NOTICE='Aplikasi ini merupakan alat bantu observasi dan pemetaan awal perilaku serta kebutuhan psikologis anak. Bukan alat diagnosis psikologis. Hasil pemetaan tidak digunakan untuk menetapkan gangguan psikologis, gangguan belajar, atau kondisi klinis. Penilaian klinis menjadi kewenangan profesional yang berkualifikasi.';
const AREAS={BL:{name:'Kesulitan Belajar',short:'Belajar',color:'#4ca29a'},PR:{name:'Perilaku & Pengaturan Diri',short:'Perilaku',color:'#edb668'},ES:{name:'Emosional & Psikososial',short:'Emosi & sosial',color:'#8eade1'}};
const IND={
 BL01:'Fokus saat kegiatan',BL02:'Mudah terdistraksi',BL03:'Mengingat instruksi',BL04:'Membaca / mengeja',BL05:'Menulis',BL06:'Konsep berhitung',BL07:'Keterlibatan belajar',
 PR01:'Aktivitas / perpindahan',PR02:'Pengendalian respons',PR03:'Interaksi fisik / konflik',PR04:'Pengelolaan waktu',PR05:'Orientasi instruksi',
 ES01:'Respons emosi',ES02:'Rasa cemas dalam konteks',ES03:'Kepercayaan diri',ES04:'Relasi teman / menarik diri',ES05:'Keamanan / perundungan',ES06:'Menghindari tugas / sekolah'
};
const LABEL_STATUS={planned:'Direncanakan',ongoing:'Berjalan',review:'Perlu ditinjau',done:'Selesai'};
const MENU=[['home','Beranda','house'],['students','Data Anak','users'],['observations','Observasi','pencil'],['signals','Peta Sinyal','activity'],['supports','Pendampingan','heart'],['reports','Laporan','file'],['guides','Panduan & Edukasi','book']];
const ICONS={house:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2"/><path d="M17 5a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5v1"/>',pencil:'<path d="M12 20h9M4 16l12-12 4 4L8 20H4z"/>',activity:'<path d="M2 12h5l3-7 4 14 3-7h5"/>',heart:'<path d="M20.8 4.6a5.3 5.3 0 0 0-7.5 0L12 5.9l-1.3-1.3a5.3 5.3 0 0 0-7.5 7.5L12 21l8.8-8.9a5.3 5.3 0 0 0 0-7.5Z"/>',file:'<path d="M6 2h8l5 5v15H6z"/><path d="M14 2v5h5M9 12h7M9 16h7"/>',book:'<path d="M3 5a3 3 0 0 1 3-3h14v19H6a3 3 0 0 1-3-3zM3 18a3 3 0 0 1 3-3h14"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>'};
function svg(name){return '<svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round">'+(ICONS[name]||ICONS.activity)+'</svg>'}
function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function fdate(d){if(!d)return 'Tidak ditentukan';const parts=String(d).split('-');return parts.length===3?`${parts[2]}/${parts[1]}/${parts[0]}`:String(d)}
function iso(d=new Date()){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function dayAgo(n){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-n);return iso(d)}
function dayAhead(n){return dayAgo(-n)}
function uid(prefix){return prefix+'-'+crypto.randomUUID()}
function escapeCsv(v){const s=String(v??'').replace(/^[=+@\-\t\r]/,x=>'\''+x);return '"'+s.replace(/"/g,'""')+'"'}
function child(code,cls){return {id:code,code,klass:cls,strength:'Memiliki minat dan kemampuan yang perlu diperhatikan saat pendampingan.'}}
function demo(){
const students=Array.from({length:12},(_,i)=>child('SIM-'+String(i+1).padStart(3,'0'),i<6?'7A':'7B'));
students[3].strength='Berminat pada praktik langsung dan kegiatan kelompok kecil.';
students[7].strength='Antusias saat kegiatan menggambar dan kerja kelompok.';
const o=(id,ch,days,area,indicator,context,prior,behavior,impact,response,strength,urgent=false)=>({id,childId:ch,date:dayAgo(days),area,indicator,context,prior,behavior,impact,response,strength,occurrence:'Satu kejadian tercatat',duration:'',author:'Guru kelas',urgent});
const observations=[
 o('OBS-001','SIM-004',13,'BL','BL01','Latihan mandiri Matematika','Guru membagikan latihan berisi lima soal.','Siswa berpindah tempat dua kali selama latihan.','Tiga soal belum dikerjakan saat waktu latihan selesai.','Guru membagi tugas menjadi dua bagian dan menjelaskan langkah pertama.','Siswa mulai mengerjakan ketika tugas dibagi.'),
 o('OBS-002','SIM-004',11,'BL','BL01','Menulis laporan kelompok','Siswa diminta menyalin hasil diskusi.','Siswa berhenti menulis beberapa kali dan menanyakan instruksi ulang.','Bagian laporan belum selesai.','Guru memberikan satu kalimat pembuka.','Siswa dapat melanjutkan dengan.'),
 o('OBS-003','SIM-004',9,'PR','PR01','Diskusi kelompok','Kelompok mulai membagi peran.','Siswa berdiri dan berjalan menuju kelompok lain sebanyak dua kali.','Satu tahap diskusi tertunda.','Guru menyampaikan aturan dan memberikan peran praktis.','Siswa mau membantu menyiapkan alat.'),
 o('OBS-004','SIM-002',8,'ES','ES03','Presentasi kelas','Guru mengundang siswa menyampaikan hasil diskusi.','Siswa mengatakan “saya belum bisa” sebelum mencoba.','Siswa belum memulai presentasi di depan kelas.','Guru menawarkan presentasi berdua.','Siswa mulai berbicara bersama temannya.'),
 o('OBS-005','SIM-008',7,'ES','ES04','Istirahat sekolah','Teman-teman sedang bermain berkelompok.','Siswa memilih duduk sendiri sepanjang satu jam istirahat.','Belum diketahui apakah siswa ingin bergabung.','Guru menyapa dan menawarkan pilihan kegiatan.','Siswa memilih menggambar.'),
 o('OBS-006','SIM-001',6,'BL','BL04','Membaca teks narasi','Guru meminta siswa membaca paragraf pendek.','Siswa meminta waktu tambahan dan mengeja beberapa kata berulang.','Kegiatan membaca membutuhkan waktu lebih panjang.','Guru memberi waktu dan membacakan pertama.','Siswa mengikuti setelah mendapat.'),
 o('OBS-007','SIM-003',5,'BL','BL06','Latihan numerasi','Guru memberi soal penjumlahan dua bilangan.','Siswa beberapa kali tertukar saat menuliskan hasil.','Dua soal memerlukan koreksi bersama.','Guru menggunakan benda konkret.','Siswa dapat menjelaskan jumlah menggunakan benda.'),
 o('OBS-008','SIM-007',4,'PR','PR04','Persiapan pergantian pelajaran','Guru meminta siswa menyiapkan buku berikutnya.','Siswa baru memulai setelah dua pengingat.','Persiapan membutuhkan waktu tambahan.','Guru menunjukkan daftar periksa sederhana.','Siswa berhasil mengambil buku.'),
 o('OBS-009','SIM-011',2,'ES','ES01','Permainan kelompok','Siswa tidak mendapat giliran pertama.','Siswa terlihat menangis dan menjauh dari kelompok.','Siswa berhenti mengikuti permainan.','Guru memberi waktu tenang dan mendengarkan penjelasan siswa.','Siswa kemudian kembali berpartisipasi.')
];
const plans=[
 {id:'SUP-001',childId:'SIM-004',action:'Instruksi bertahap dengan konkret dan daftar cek kegiatan belajar.',owner:'Guru kelas',startDate:dayAgo(10),reviewDate:dayAhead(3),status:'ongoing',result:'Respons awal: mulai bekerja ketika langkah dibagi.',observationId:'OBS-001'},
 {id:'SUP-002',childId:'SIM-002',action:'Latihan presentasi dalam kelompok kecil dan umpan balik positif.',owner:'Wali kelas',startDate:dayAgo(7),reviewDate:dayAhead(5),status:'ongoing',result:'Mau mencoba presentasi berdua.',observationId:'OBS-004'},
 {id:'SUP-003',childId:'SIM-008',action:'Ajak berbincang untuk memahami pilihan aktivitas saat istirahat tanpa memaksa interaksi.',owner:'Guru BK',startDate:dayAgo(5),reviewDate:dayAhead(7),status:'planned',result:'',observationId:'OBS-005'},
 {id:'SUP-004',childId:'SIM-003',action:'Latihan penjumlahan dengan benda konkret secara bertahap.',owner:'Guru Matematika',startDate:dayAgo(4),reviewDate:dayAgo(1),status:'review',result:'Perlu meninjau hasil latihan berikutnya.',observationId:'OBS-007'}
];
return {students,observations,plans};
}
let data={students:[],observations:[],plans:[]};
let state={view:'home',student:'SIM-004',reportStudent:'SIM-004',obsFilter:'',studentFilter:'',signalsTab:'summary',editingObs:null,editingPlan:null,editingChild:null,mobile:false,safetyShown:false};
const byChild=id=>data.observations.filter(x=>x.childId===id).sort((a,b)=>b.date.localeCompare(a.date));
const plansChild=id=>data.plans.filter(x=>x.childId===id);
const getStudent=id=>data.students.find(s=>s.id===id);
const childCode=id=>getStudent(id)?.code||'Profil dihapus';
const countsByArea=(o)=>Object.keys(AREAS).map(k=>({key:k,count:o.filter(v=>v.area===k).length}));
function notify(msg){const t=root.getElementById('toast');if(!t)return;t.textContent=msg;t.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>{t.hidden=true},5000)}
function optsStudents(selected,all=false){return (all?'<option value="all">Semua kode anak</option>':'')+data.students.map(s=>`<option value="${esc(s.id)}" ${s.id===selected?'selected':''}>${esc(s.code)} • Kelas ${esc(s.klass)}</option>`).join('')}
function areaOptions(v){return Object.entries(AREAS).map(([k,a])=>`<option value="${k}" ${k===v?'selected':''}>${esc(a.name)}</option>`).join('')}
function indicators(area,selected){return Object.entries(IND).filter(([key])=>key.startsWith(area)).map(([key,label])=>`<option value="${key}" ${key===selected?'selected':''}>${key} — ${esc(label)}</option>`).join('')}
function disclaimer(){return `<div class="notice" role="note"><div class="mark" aria-hidden="true">!</div><div><strong>PENTING — BUKAN ALAT DIAGNOSIS PSIKOLOGIS</strong><p>${esc(LONG_NOTICE)}</p></div></div>`}
function modeBanner(){return mode==='demo'?'<div class="mode-note"><strong>MODE LATIHAN — SEMUA DATA FIKTIF.</strong> Perubahan latihan hanya berada di memori halaman dan hilang saat muat ulang. Data lokal terenkripsi Anda tetap terpisah.</div>':'<div class="mode-note"><strong>MODE LOKAL TERENKRIPSI.</strong> Satu petugas dan satu perangkat. Gunakan kode samaran. Cadangkan secara berkala; data tidak tersinkron ke server. Saat terbuka, catatan dapat dibaca oleh skrip lain pada domain WSP yang sama. Gunakan perangkat dan halaman tepercaya.</div>'}
function shell(){const navKey=state.view==='observation-form'?'observations':state.view==='plan-form'?'supports':state.view==='child-form'?'students':state.view;
const urgent=data.observations.filter(o=>o.urgent);
return `<div class="mobile-backdrop ${state.mobile?'open':''}" data-action="close-menu" aria-hidden="true"></div><div class="app-shell"><aside class="sidebar ${state.mobile?'open':''}" id="app-navigation"><div class="brand"><img class="brand-logo" src="${BRAND_LOGO}" alt="Edumind Academy"></div><div class="product-label">PEMETAAN SINYAL<br>PSIKOLOGIS ANAK</div><nav class="nav-items" aria-label="Menu utama">${MENU.map(([key,label,ic],i)=>`<button type="button" data-action="navigate" data-target="${key}" class="nav-btn ${navKey===key?'active':''}" ${navKey===key?'aria-current="page"':''}><span class="nav-idx">${String(i+1).padStart(2,'0')}</span>${svg(ic)}<span>${esc(label)}</span></button>`).join('')}</nav><div class="nav-bottom">${esc(DISCLAIMER)}<br><br>Versi ${VERSION}<br>${mode==='demo'?'Latihan fiktif':'Data lokal terenkripsi'}.</div></aside><div class="main-wrap"><div class="main-inner"><header class="topbar"><div><button type="button" class="top-button mobile-menu" data-action="toggle-menu" aria-label="Buka menu" aria-expanded="${state.mobile}" aria-controls="app-navigation">☰ Menu</button><div class="school-name">Pemetaan Sinyal Psikologis Anak</div><div class="tiny">Edumind Academy · Observasi dan pendampingan pendidikan</div></div><div class="top-actions"><span class="sim-badge">${mode==='demo'?'LATIHAN FIKTIF':'LOKAL TERENKRIPSI'}</span>${mode==='live'?btn('Cadangkan','backup','top-button')+btn('Pulihkan','restore','top-button')+(APP_VARIANT==='personal'?btn('Ubah Password','change-password','top-button'):''):btn('Atur ulang latihan','reset','top-button')}${btn(mode==='live'?'Keluar':'Keluar Simulasi','lock','top-button')}</div></header>${disclaimer()}${modeBanner()}${workspaceSwitch()}<div id="storage-state" class="storage-state" role="status" aria-live="polite"></div>${urgent.length?`<div class="persistent-urgent" role="note"><b>${urgent.length} catatan keselamatan perlu ditindaklanjuti sesuai SOP.</b> Penanda ini berasal dari pencatat, bukan skor otomatis. ${btn('Lihat catatan','navigate','btn small','data-target="observations"')}</div>`:''}<main id="main-content">${renderView()}</main><footer class="footer">Edumind Academy · Versi ${VERSION} · Bukan diagnosis atau instrumen psikometrik tervalidasi. Data tidak dikirim ke Edumind oleh kode aplikasi. ${btn('Kosongkan data mode ini','clear','btn danger small')}</footer></div></div></div>`;
}

function title(t,desc='',action=''){return `<div class="title-row"><div><h1 class="page-title">${esc(t)}</h1>${desc?`<p class="page-sub">${esc(desc)}</p>`:''}</div>${action?`<div class="title-actions">${action}</div>`:''}</div>`}
function btn(label,action,cls='btn',extras=''){return `<button type="button" class="${cls}" data-action="${action}" ${extras}>${label}</button>`}
function card(body,extra=''){return `<section class="card ${extra}">${body}</section>`}
function chartRows(observations){const cs=countsByArea(observations),max=Math.max(1,...cs.map(x=>x.count));return `<div class="chart-rows">${cs.map(x=>`<div class="chart-row"><span>${esc(AREAS[x.key].short)}</span><div class="bar-track" role="img" aria-label="${esc(AREAS[x.key].name)}: ${x.count} catatan"><div class="bar-fill" style="width:${x.count/max*100}%"></div></div><strong>${x.count}</strong></div>`).join('')}</div><p class="search-note">Panjang batang = jumlah catatan, bukan skor atau persentase risiko.</p>`}
function home(){const open=data.plans.filter(x=>x.status!=='done').length;const due=data.plans.filter(x=>x.status!=='done'&&x.reviewDate<=dayAhead(7)).length;const latest=[...data.observations].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);
return title('Pendampingan yang terarah','Mulai dari pengamatan faktual, bukan pelabelan anak.',btn('+ Catat observasi','new-observation','btn primary'))+`<div class="grid stats"><div class="stat"><div class="lbl">Profil anak</div><div class="number">${data.students.length}</div><div class="tiny">Profil berkode</div></div><div class="stat"><div class="lbl">Catatan observasi</div><div class="number">${data.observations.length}</div><div class="tiny">Entri pengamatan</div></div><div class="stat"><div class="lbl">Dukungan belum selesai</div><div class="number">${open}</div><div class="tiny">Status administratif</div></div><div class="stat"><div class="lbl">Peninjauan ≤ 7 hari/terlewat</div><div class="number">${due}</div><div class="tiny">Bukan tingkat risiko</div></div></div><div class="grid two">${card(`<div class="card-head"><div><h3>Catatan observasi terbaru</h3><div class="tiny">Berbasis kejadian yang benar-benar tercatat</div></div>${btn('Lihat semua','navigate','btn small','data-target="observations"')}</div>${latest.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Tanggal</th><th>Kode anak</th><th>Area / indikator</th><th>Aksi</th></tr></thead><tbody>${latest.map(o=>`<tr><td>${fdate(o.date)}</td><td>${esc(childCode(o.childId))}</td><td>${esc(AREAS[o.area]?.short||'')}<div class="tiny">${esc(IND[o.indicator]||'')}</div></td><td>${btn('Lihat','view-child','btn small',`data-id="${esc(childCode(o.childId))}"`)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada observasi. Tidak berarti anak tidak memiliki kesulitan.</div>'}`)}${card(`<h3>Rekap area observasi</h3><div class="tiny">Jumlah entri per kelompok pada data yang dibuka</div>${chartRows(data.observations)}${btn('Buka Peta Sinyal →','navigate','btn','data-target="signals"')}`)}</div><div class="grid two" style="margin-top:14px">${card(`<h3>Tindak lanjut terdekat</h3><div class="tiny">Ditentukan dan diperiksa manusia</div><div class="timeline">${data.plans.filter(p=>p.status!=='done').sort((a,b)=>a.reviewDate.localeCompare(b.reviewDate)).slice(0,4).map(p=>`<div class="time-item"><div class="time-meta">${esc(childCode(p.childId))} · Tinjau ${fdate(p.reviewDate)}</div><div class="time-title">${esc(p.action)}</div><span class="pill ${p.status==='review'?'amber':'green'}">${LABEL_STATUS[p.status]||'Ditinjau'}</span></div>`).join('')||'<div class="empty">Belum ada rencana pendampingan.</div>'}</div>`)}${card(`<h3>Prinsip membaca hasil</h3><p class="muted">Satu perilaku dapat mempunyai banyak konteks. Guru mencatat yang tampak, menanyakan informasi yang belum diketahui, dan menguji apakah dukungan pendidikan membantu.</p><div class="help-strip"><b>Belum ada data ≠ tidak ada masalah.</b><br>Jumlah catatan yang lebih banyak juga tidak otomatis berarti tingkat gangguan lebih berat.</div><div class="warning-strip"><b>Keselamatan lebih utama.</b><br>Bila ada dugaan kekerasan, ancaman, atau bahaya segera, ikuti prosedur perlindungan anak dan cari bantuan yang tepat, tanpa menunggu skor atau jumlah observasi.</div>${btn('Baca panduan dan prosedur','navigate','btn','data-target="guides"')}`)}</div>`}
function students(){const q=state.studentFilter.toLowerCase().trim();const arr=data.students.filter(s=>`${s.code} ${s.klass}`.toLowerCase().includes(q));return title('Data Anak','Gunakan kode samaran dan catat informasi seperlunya.',btn('+ Tambah profil anak','new-child','btn primary'))+card(`<div class="toolbar"><div class="field" style="flex:1"><label for="child-search">Cari kode / kelas</label><input id="child-search" placeholder="Contoh: SIM-004 atau 7A" value="${esc(state.studentFilter)}"></div><div class="search-note">${arr.length} profil ditampilkan</div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Kode siswa</th><th>Kelas</th><th>Observasi</th><th>Dukungan</th><th>Aksi</th></tr></thead><tbody>${arr.map(s=>`<tr><td><b>${esc(s.code)}</b><div class="tiny">Profil berkode</div></td><td>${esc(s.klass)}</td><td>${byChild(s.id).length} catatan</td><td>${plansChild(s.id).length} rencana</td><td class="td-actions">${btn('Peta','view-child','btn small',`data-id="${esc(s.id)}"`)} ${btn('Ubah','edit-child','btn small',`data-id="${esc(s.id)}"`)} ${btn('Hapus','delete-child','btn danger small',`data-id="${esc(s.id)}"`)}</td></tr>`).join('')}</tbody></table></div>${arr.length?'':'<div class="empty">Belum ditemukan.</div>'}`)+`<div class="help-strip">Gunakan kode samaran. Simpan daftar penghubung kode dan identitas secara terpisah sesuai kebijakan sekolah.</div>`}
function childForm(){const x=state.editingChild?getStudent(state.editingChild):null;return title(x?'Ubah profil anak':'Tambah profil anak','Kode samaran membantu membatasi identitas yang tersimpan.')+`<form id="child-form">${card(`<div class="form-grid"><div class="field"><label for="child-code">Kode unik anak <span class="req">*</span></label><input id="child-code" name="code" required maxlength="24" pattern="[A-Za-z0-9-]+" placeholder="Misalnya SIM-013" value="${esc(x?.code||'')}"><small>Huruf, angka, dan tanda hubung. Jangan nama asli.</small></div><div class="field"><label for="child-class">Kelas/tahap <span class="req">*</span></label><input id="child-class" name="klass" required maxlength="24" placeholder="7A" value="${esc(x?.klass||'')}"></div><div class="field wide"><label for="child-strength">Kekuatan dan minat yang terlihat</label><textarea name="strength" id="child-strength" maxlength="500" placeholder="Contoh: suka menggambar dan merespons baik instruksi visual">${esc(x?.strength||'')}</textarea></div></div><div class="form-footer">${btn('Batal','navigate','btn','data-target="students"')}<button type="submit" class="btn primary">Simpan profil anak</button></div>`)}</form>`}
function observations(){const q=state.obsFilter;const arr=data.observations.filter(o=>!q||o.childId===q).sort((a,b)=>b.date.localeCompare(a.date));return title('Observasi','Catat kejadian yang teramati pada konteks tertentu, beserta kekuatan dan respons anak.',btn('+ Catat observasi','new-observation','btn primary'))+card(`<div class="toolbar"><div class="field"><label for="obs-filter">Filter kode anak</label><select id="obs-filter"><option value="">Semua anak</option>${optsStudents(q)}</select></div><div class="search-note">${arr.length} observasi tercatat</div></div>${arr.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Tanggal</th><th>Kode</th><th>Area / indikator</th><th>Kegiatan / pengamatan</th><th>Aksi</th></tr></thead><tbody>${arr.map(o=>`<tr><td>${fdate(o.date)}</td><td><b>${esc(childCode(o.childId))}</b></td><td>${esc(AREAS[o.area]?.short||'')}<br><span class="tiny">${esc(IND[o.indicator]||'')}</span></td><td>${esc(o.context)}<div class="tiny">${esc(o.behavior.slice(0,85))}${o.behavior.length>85?'…':''}</div>${o.urgent?'<span class="pill red">Perlu prosedur keselamatan</span>':''}</td><td class="td-actions">${btn('Ubah','edit-observation','btn small',`data-id="${esc(o.id)}"`)} ${btn('Hapus','delete-observation','btn danger small',`data-id="${esc(o.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada catatan. Ini bukan pernyataan kondisi anak.</div>'}`)+`<div class="help-strip"><b>Pedoman:</b> tulis “siswa bangkit dari kursi dua kali”, bukan “siswa ADHD”. Catat konteks, respons dan kekuatan anak.</div>`}
function obsForm(){const o=state.editingObs?data.observations.find(x=>x.id===state.editingObs):null;const area=o?.area||'BL';return title(o?'Ubah catatan observasi':'Tambah catatan observasi','Observasi pendidikan — bukan instrumen diagnosis.')+`<form id="observation-form"><div class="form-section"><h3>1. Informasi dasar</h3><div class="form-grid"><div class="field"><label for="obs-child">Kode anak <span class="req">*</span></label><select id="obs-child" name="childId" required>${optsStudents(o?.childId||state.student)}</select></div><div class="field"><label for="obs-date">Tanggal observasi <span class="req">*</span></label><input id="obs-date" type="date" name="date" max="${iso()}" required value="${esc(o?.date||iso())}"></div><div class="field wide"><label for="obs-context">Kegiatan / lokasi / situasi <span class="req">*</span></label><input id="obs-context" name="context" required maxlength="180" placeholder="Contoh: latihan Matematika di kelas" value="${esc(o?.context||'')}"></div></div></div><div class="form-section"><h3>2. Area dan indikator pengamatan</h3><div class="form-grid"><div class="field"><label for="obs-area">Kelompok observasi <span class="req">*</span></label><select id="obs-area" name="area" required>${areaOptions(area)}</select></div><div class="field"><label for="obs-indicator">Indikator deskriptif <span class="req">*</span></label><select id="obs-indicator" name="indicator" required>${indicators(area,o?.indicator)}</select></div></div></div><div class="form-section"><h3>3. Catatan faktual dan konteks</h3><div class="form-grid"><div class="field"><label for="obs-prior">Apa yang terjadi sebelumnya? <span class="req">*</span></label><textarea id="obs-prior" name="prior" required maxlength="1500" placeholder="Instruksi, kegiatan atau situasi yang mendahului">${esc(o?.prior||'')}</textarea></div><div class="field"><label for="obs-behavior">Apa yang benar-benar terlihat/terdengar? <span class="req">*</span></label><textarea id="obs-behavior" name="behavior" required maxlength="1500" placeholder="Catatan perilaku atau ucapan anak, bukan dugaan diagnosis">${esc(o?.behavior||'')}</textarea></div><div class="field"><label for="obs-impact">Dampak terhadap kegiatan</label><textarea id="obs-impact" name="impact" maxlength="800" placeholder="Dampak yang terlihat, jika diketahui">${esc(o?.impact||'')}</textarea></div><div class="field"><label for="obs-response">Dukungan yang dicoba dan respons anak</label><textarea id="obs-response" name="response" maxlength="1000" placeholder="Apa yang guru lakukan? Bagaimana respons anak?">${esc(o?.response||'')}</textarea></div><div class="field wide"><label for="obs-strength">Kekuatan, minat atau kondisi yang membantu <span class="req">*</span></label><textarea id="obs-strength" name="strength" required maxlength="900" placeholder="Catat keberhasilan sekecil apa pun dan situasi yang membantu">${esc(o?.strength||'')}</textarea></div><div class="field"><label for="obs-occurrence">Frekuensi yang benar-benar dicatat</label><select id="obs-occurrence" name="occurrence">${['Belum diketahui','Satu kejadian tercatat','Dua kejadian tercatat','Tiga kejadian atau lebih tercatat'].map(v=>`<option ${v===(o?.occurrence||'Belum diketahui')?'selected':''}>${v}</option>`).join('')}</select><small>Jangan menebak frekuensi jika belum diamati.</small></div><div class="field"><label for="obs-duration">Durasi (bila diketahui)</label><input id="obs-duration" name="duration" maxlength="80" placeholder="Contoh: sekitar 4 menit" value="${esc(o?.duration||'')}"></div><div class="field"><label for="obs-author">Peran pencatat <span class="req">*</span></label><select id="obs-author" name="author" required>${['Guru kelas','Wali kelas','Guru BK','Guru mata pelajaran','Koordinator'].map(x=>`<option ${x===(o?.author||'Guru kelas')?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="obs-urgent">Catatan keselamatan</label><label class="choice" for="obs-urgent"><input id="obs-urgent" type="checkbox" name="urgent" ${o?.urgent?'checked':''}> Ada indikasi situasi yang memerlukan prosedur keselamatan anak</label></div></div><div class="warning-strip">Jika ada ancaman, kekerasan, atau bahaya segera, prioritaskan perlindungan dan pertolongan sesuai prosedur sekolah. Jangan menunggu kelengkapan form, pola berulang atau skor.</div></div><div class="form-footer">${btn('Batal','navigate','btn','data-target="observations"')}<button type="submit" class="btn primary">Simpan observasi</button></div></form>`}
function signalSummary(s,obs){const areaCounts=countsByArea(obs),countIndicator={};obs.forEach(o=>countIndicator[o.indicator]=(countIndicator[o.indicator]||0)+1);const lines=Object.entries(countIndicator).sort((a,b)=>b[1]-a[1]);const max=Math.max(1,...lines.map(x=>x[1]));return `<div class="grid two">${card(`<h3>Gambaran umum</h3><p class="muted">${obs.length} catatan observasi pada profil ini. Semua kesimpulan memerlukan peninjauan konteks oleh pendidik.</p><div class="help-strip"><b>Peta ini bukan tes psikologi.</b><br>Tidak memberikan label atau diagnosis.</div><div class="report-grid"><div><b>${obs.length}</b><span class="tiny">Catatan</span></div><div><b>${new Set(obs.map(x=>x.date)).size}</b><span class="tiny">Hari berbeda</span></div><div><b>${plansChild(s.id).length}</b><span class="tiny">Rencana</span></div></div>`)}${card(`<h3>Area yang tercatat</h3>${obs.length?chartRows(obs):'<div class="empty">Belum ada data observasi; bukan berarti tidak ada kebutuhan.</div>'}<p class="tiny">Area ditentukan oleh kategori formulir yang dipilih guru.</p>`)}</div><div class="grid two" style="margin-top:14px">${card(`<h3>Rincian indikator tercatat</h3>${lines.length?`<div class="signal-list">${lines.map(([code,n])=>`<div class="signal-line"><div><span class="signal-dot"></span>${esc(IND[code]||code)}</div><div class="bar-track"><div class="bar-fill" style="width:${n/max*100}%"></div></div><b>${n} catatan</b></div>`).join('')}</div>`:'<div class="empty">Belum ada indikator yang tercatat.</div>'}<div class="tiny">Jumlah catatan, bukan besarnya masalah atau peluang diagnosis.</div>`,'strength-card')}${card(`<h3>Kekuatan dan respons yang membantu</h3><p class="muted">${esc(s.strength||'Belum dicatat.')}</p>${obs.length?`<ul>${obs.slice(0,4).map(x=>`<li>${esc(x.strength||x.response||'Belum dicatat')}</li>`).join('')}</ul>`:'<p class="muted">Lengkapi melalui catatan observasi.</p>'}<div class="help-strip">Penetapan dukungan dilakukan guru dan sekolah dengan mempertimbangkan suara anak dan keluarga.</div>`,'support-card')}</div>`}
function signalTimeline(obs){return card(`<h3>Garis waktu observasi</h3>${obs.length?`<div class="timeline">${obs.map(o=>`<div class="time-item"><div class="time-meta">${fdate(o.date)} · ${esc(o.context)} · ${esc(o.author)}</div><div class="time-title">${esc(IND[o.indicator]||o.indicator)}</div><div class="info-pair"><div class="key">Sebelum</div><div>${esc(o.prior)}</div><div class="key">Teramati</div><div>${esc(o.behavior)}</div><div class="key">Dukungan</div><div>${esc(o.response||'Belum dicatat')}</div><div class="key">Kekuatan</div><div>${esc(o.strength||'Belum dicatat')}</div></div>${o.urgent?'<div class="app-alert"><b>Catatan keselamatan:</b> ikuti prosedur perlindungan sekolah; jangan menunggu skor.</div>':''}</div>`).join('')}</div>`:'<div class="empty">Belum ada catatan observasi.</div>'}`)}
function signals(){const s=getStudent(state.student);if(!s)return title('Peta Sinyal','Tambahkan profil anak dahulu.');const obs=byChild(s.id);const pc=plansChild(s.id);return title('Peta Sinyal','Pola dari observasi pendidikan yang tercatat, bukan hasil asesmen klinis.',btn('+ Catat observasi','new-observation','btn primary'))+`<div class="toolbar"><div class="field"><label for="signal-child">Kode anak</label><select id="signal-child">${optsStudents(s.id)}</select></div></div>${card(`<div class="student-header"><div class="avatar" aria-hidden="true">${esc(s.code.slice(-2))}</div><div><h3 style="margin:0">${esc(s.code)} · Kelas ${esc(s.klass)}</h3><div class="tiny">Identitas menggunakan kode samaran · ${obs.length} catatan tercatat</div></div></div><div class="tabs" role="group" aria-label="Rincian Peta Sinyal">${[['summary','Ringkasan'],['timeline','Catatan & riwayat'],['supports','Pendampingan']].map(([id,label])=>`<button type="button" aria-pressed="${state.signalsTab===id?'true':'false'}" data-action="signal-tab" data-id="${id}" class="tab ${state.signalsTab===id?'active':''}">${label}</button>`).join('')}</div><div class="help-strip"><b>Alat bantu observasi dan pemetaan awal. Bukan alat diagnosis psikologis.</b> Indikator menunjukkan catatan yang dipilih guru, bukan skor risiko anak.</div>${state.signalsTab==='summary'?signalSummary(s,obs):state.signalsTab==='timeline'?signalTimeline(obs):`<h3>Rencana dukungan ${esc(s.code)}</h3>${supportTable(pc)}${btn('+ Tambah rencana','new-plan','btn primary')}`}`)}`}
function supportTable(plans){return plans.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Kode</th><th>Rencana tindakan</th><th>Penanggung jawab</th><th>Tinjau</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${plans.map(p=>`<tr><td>${esc(childCode(p.childId))}</td><td>${esc(p.action)}${p.result?`<div class="tiny">Hasil: ${esc(p.result)}</div>`:''}</td><td>${esc(p.owner)}</td><td>${fdate(p.reviewDate)}</td><td><span class="pill ${p.status==='done'?'green':p.status==='review'?'amber':'blue'}">${esc(LABEL_STATUS[p.status]||p.status)}</span></td><td class="td-actions">${btn('Ubah','edit-plan','btn small',`data-id="${esc(p.id)}"`)} ${btn('Hapus','delete-plan','btn danger small',`data-id="${esc(p.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada rencana. Pendampingan ditetapkan oleh guru/pihak berwenang, bukan otomatis.</div>'}
function supports(){return title('Pendampingan','Tindakan, penanggung jawab, dan jadwal peninjauan ditentukan oleh pendidik.',btn('+ Buat rencana','new-plan','btn primary'))+card(`<h3>Rencana dan tindak lanjut</h3><div class="tiny" style="margin-bottom:12px">Status adalah status pekerjaan, bukan kesimpulan kondisi psikologis anak.</div>${supportTable([...data.plans].sort((a,b)=>a.reviewDate.localeCompare(b.reviewDate)))}`)+`<div class="help-strip">Pilihan dukungan berfokus pada akses belajar, interaksi aman, koordinasi keluarga dan rujukan sesuai kewenangan. Aplikasi tidak memberi resep, terapi klinis, atau diagnosis.</div>`}
function planForm(){const p=state.editingPlan?data.plans.find(x=>x.id===state.editingPlan):null;return title(p?'Ubah rencana dukungan':'Tambah rencana pendampingan','Tentukan tindakan pendidikan yang aman dan bisa dievaluasi.')+`<form id="plan-form">${card(`<div class="form-grid"><div class="field"><label for="plan-child">Kode anak <span class="req">*</span></label><select id="plan-child" name="childId">${optsStudents(p?.childId||state.student)}</select></div><div class="field"><label for="plan-obs">Rujukan catatan observasi</label><select id="plan-obs" name="observationId"><option value="">Tidak dipilih</option>${data.observations.filter(o=>o.childId===(p?.childId||state.student||data.students[0]?.id)).map(o=>`<option value="${esc(o.id)}" ${o.id===p?.observationId?'selected':''}>${esc(o.id)} · ${esc(childCode(o.childId))} · ${esc(IND[o.indicator]||'')}</option>`).join('')}</select><small>Hanya catatan pada anak yang sama akan diterima saat disimpan.</small></div><div class="field wide"><label for="plan-action">Tindakan pendampingan <span class="req">*</span></label><textarea id="plan-action" name="action" required maxlength="1500" placeholder="Contoh: berikan instruksi singkat bertahap lalu tinjau respons siswa">${esc(p?.action||'')}</textarea></div><div class="field"><label for="plan-owner">Penanggung jawab <span class="req">*</span></label><select id="plan-owner" name="owner">${['Guru kelas','Wali kelas','Guru BK','Guru Matematika','Guru Bahasa Indonesia','Koordinator'].map(x=>`<option ${x===(p?.owner||'Guru kelas')?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="plan-status">Status administratif</label><select id="plan-status" name="status">${Object.entries(LABEL_STATUS).map(([k,v])=>`<option value="${k}" ${k===(p?.status||'planned')?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="plan-start">Tanggal mulai <span class="req">*</span></label><input id="plan-start" type="date" name="startDate" required value="${esc(p?.startDate||iso())}"></div><div class="field"><label for="plan-review">Tanggal tinjau <span class="req">*</span></label><input id="plan-review" type="date" name="reviewDate" required value="${esc(p?.reviewDate||dayAhead(7))}"></div><div class="field wide"><label for="plan-result">Hasil peninjauan / respons anak</label><textarea id="plan-result" name="result" maxlength="1500" placeholder="Catat hasil yang teramati. Kosong jika belum ditinjau.">${esc(p?.result||'')}</textarea></div></div><div class="form-footer">${btn('Batal','navigate','btn','data-target="supports"')}<button type="submit" class="btn primary">Simpan rencana</button></div>`)}</form>`}
function reports(){const s=getStudent(state.reportStudent);if(!s)return title('Laporan','Tidak ada profil anak.');const obs=byChild(s.id),plans=plansChild(s.id),counts=countsByArea(obs);const report=`<section class="card report-doc" id="report-paper"><div class="only-print">EDUMIND ACADEMY · ${mode==='demo'?'SIMULASI':'CATATAN LOKAL'}</div><div class="report-title">Laporan Observasi Pendidikan ${mode==='demo'?'— SIMULASI':''}</div><div class="tiny">${esc(DISCLAIMER)} · Dicetak ${fdate(iso())}</div><div class="report-grid"><div><span class="tiny">Kode anak</span><b>${esc(s.code)}</b></div><div><span class="tiny">Kelas</span><b>${esc(s.klass)}</b></div><div><span class="tiny">Catatan</span><b>${obs.length}</b></div></div><h3>Rekap jumlah catatan</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Area</th><th>Catatan</th><th>Batas interpretasi</th></tr></thead><tbody>${counts.map(x=>`<tr><td>${esc(AREAS[x.key].name)}</td><td>${x.count}</td><td>Jumlah catatan yang tersedia; bukan besarnya gangguan.</td></tr>`).join('')}</tbody></table></div><h3 style="margin-top:19px">Kekuatan anak dan dukungan yang membantu</h3><p>${esc(s.strength||'Belum dicatat')}</p><ul>${obs.slice(0,5).map(o=>`<li>${esc(o.strength||o.response||'Belum dicatat')}</li>`).join('')||'<li>Belum ada catatan.</li>'}</ul><h3>Rangkuman observasi per kejadian</h3>${obs.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Tanggal</th><th>Situasi</th><th>Yang teramati</th><th>Dukungan / respons</th></tr></thead><tbody>${obs.map(o=>`<tr><td>${fdate(o.date)}</td><td>${esc(o.context)}<br><b>Sebelum:</b> ${esc(o.prior)}<br><b>Pencatat:</b> ${esc(o.author)}<br><b>Frekuensi:</b> ${esc(o.occurrence)}<br><b>Durasi:</b> ${esc(o.duration||'Belum diketahui')}</td><td>${esc(o.behavior)}<br><b>Dampak:</b> ${esc(o.impact||'Belum dicatat')}${o.urgent?'<p><b>KESELAMATAN: ikuti SOP segera</b></p>':''}</td><td>${esc(o.response||'Belum dicatat')}<br><b>Kekuatan:</b> ${esc(o.strength)}</td></tr>`).join('')}</tbody></table></div>`:'<p>Belum ada observasi. Ini tidak berarti siswa tidak memiliki kesulitan.</p>'}<h3 style="margin-top:19px">Rencana pendampingan</h3>${plans.length?`<ol>${plans.map(p=>`<li>${esc(p.action)} — ${esc(p.owner)} (mulai ${fdate(p.startDate)}, tinjau ${fdate(p.reviewDate)}, ${esc(LABEL_STATUS[p.status]||'')}). Hasil: ${esc(p.result||'Belum ditinjau')}.</li>`).join('')}</ol>`:'<p>Belum ada rencana pendampingan.</p>'}<div class="report-legal app-alert"><b>PERNYATAAN WAJIB:</b> ${esc(LONG_NOTICE)}<br><b>Dokumen ini merupakan catatan observasi pendidikan, bukan hasil tes psikologi dan tidak dapat digunakan sebagai surat keterangan diagnosis.</b></div><div class="tiny">Dokumen memuat informasi terbatas. Bagikan hanya kepada pihak berwenang.</div></section>`;
return title('Laporan','Buat dan cetak ringkasan deskriptif yang memuat batasan penggunaan.',btn('Cetak / Simpan PDF','print-report','btn primary')+btn('Unduh CSV rekap agregat','export-csv','btn'))+`<div class="toolbar hide-print"><div class="field"><label for="report-child">Profil anak</label><select id="report-child">${optsStudents(s.id)}</select></div></div>${report}${exportsPanel()}`}
function guides(){return title('Panduan & Edukasi','Catatan pendidikan untuk memahami kebutuhan dan meninjau dukungan anak.')+`<div class="grid two">${card(`<h3>Urutan kerja</h3><ol><li>Pilih Coba Data Simulasi di halaman masuk atau pada bagian Ruang Data Kerja. Kembali melalui tombol Kembali ke Data Kerja; perubahan simulasi tidak digabungkan. Mode lokal terenkripsi dimulai kosong.</li><li>Buat profil dengan kode samaran; pisahkan daftar kode dan identitas di tempat yang terkendali.</li><li>Catat satu kejadian: situasi, hal yang mendahului, perilaku teramati, dampak, dukungan, respons, dan kekuatan anak.</li><li>Baca Peta Sinyal bersama konteks. Batang menunjukkan jumlah entri; pilihan frekuensi tidak menggandakan jumlah entri.</li><li>Tentukan tindakan pendidikan, penanggung jawab, tanggal mulai, serta tanggal tinjau.</li><li>Catat hasil peninjauan sebelum menandai rencana selesai.</li><li>Cetak laporan bila perlu, lalu unduh cadangan terenkripsi dan kunci aplikasi.</li></ol>`)}${card(`<h3>Membaca peta dengan tepat</h3><p>Satu perilaku dapat memiliki beberapa konteks. Jumlah catatan bukan tingkat gangguan, persentase risiko, diagnosis, atau kepastian sebab. Belum ada catatan bukan berarti anak tidak memiliki kebutuhan.</p><p>Periksa akses instruksi, bahasa, pendengaran dan penglihatan, tuntutan tugas, situasi kelas, rasa aman, serta informasi dari anak dan keluarga. Catat sebagai informasi yang perlu ditelaah; jangan menetapkan sebab otomatis.</p><p>Contoh: tulis “berpindah tempat dua kali selama menulis”, bukan “ADHD”; “belum memulai setelah instruksi”, bukan “malas”.</p>`)}${card(`<h3>Dukungan yang dapat ditinjau</h3><p>Pilih satu target pendidikan yang teramati, misalnya anak memulai satu langkah tugas dengan instruksi visual. Catat dukungan yang dicoba dan respons aktual, kemudian tentukan kapan ditinjau.</p><p>Bandingkan konteks dan hasil, dengarkan anak, dan koordinasikan dengan keluarga serta petugas sekolah sesuai peran. Kesulitan menetap, menimbulkan distres, atau mengganggu kegiatan perlu dibicarakan dengan profesional berkualifikasi. Dukungan kelas tidak perlu menunggu diagnosis.</p>`)}${card(`<h3>Keselamatan dan perlindungan</h3><p>Jika ada ancaman atau bahaya, utamakan perlindungan dan pertolongan segera sesuai SOP sekolah. Jangan menunggu pengisian form, pengulangan kejadian, atau hasil peta.</p><p>Jangan melakukan interogasi, menyebarkan catatan, menyalahkan korban, atau menjanjikan kerahasiaan mutlak. Libatkan petugas perlindungan dan profesional sesuai kebutuhan. Penanda keselamatan tetap terlihat sampai pencatat meninjau catatan tersebut. Rencana selesai tidak otomatis menghapus penanda.</p>`)}${card(`<h3>Penyimpanan dan pemulihan</h3><p>Mode lokal mengenkripsi data di browser dengan AES-GCM. ${APP_VARIANT==='personal'?'Login menggunakan username dan password pilihan pengguna pada browser ini.':'Login memakai username dan password bersama yang ditetapkan Edumind.'} Password akses tidak dikirim ke server oleh aplikasi. ${APP_VARIANT==='personal'?'Simpan password pribadi karena Edumind tidak dapat memulihkannya;':'Akses bersama tidak memisahkan kewenangan antar pengguna;'} gunakan kode samaran dan perangkat tepercaya. Enkripsi melindungi data yang tersimpan saat terkunci; ketika aplikasi terbuka, perangkat dan skrip pada domain yang sama tetap harus dipercaya.</p><p>Kunci otomatis setelah 10 menit tanpa interaksi. Perubahan formulir yang belum disimpan akan hilang saat dikunci. Simpan sebelum meninggalkan perangkat. Jika penyimpanan gagal, peringatan tetap tampil; segera unduh cadangan.</p><p>Excel berisi salinan seluruh profil, observasi, pendampingan, dan rekap. Excel tidak terenkripsi dan tidak diimpor kembali ke aplikasi. Cadangan .edumind berisi data terenkripsi dan dipulihkan dengan akun yang sesuai untuk versi aplikasi ini. Cadangan versi sebelumnya meminta frasa sandi lamanya. Pulihkan mengganti seluruh data pada perangkat ini. Bukan penggabungan. Menghapus data browser, berganti browser/domain, atau kehilangan perangkat bisa menghilangkan data lokal. Data versi sebelumnya tetap memerlukan frasa sandi lama untuk penyesuaian pertama.</p><p>CSV hanya berisi rekap jumlah per area, bukan cadangan. Laporan PDF/cetak tidak terenkripsi; kendalikan penerima dan penyimpanannya.</p>`)}${card(`<h3>Dasar materi dan batas penggunaan</h3><p>Webinar Edumind Academy “Mengungkap Akar Psikologis Anak”, sesi 16 Oktober 2026, narasumber Trubus Raharjo. Slide membahas “Memahami Akar Masalah Perilaku Siswa dan Strategi Pendampingan”. Tiga area digunakan sebagai pengelompokan catatan pendidikan.</p><p>Indikator dan fitur aplikasi merupakan pengembangan operasional Edumind, bukan instrumen psikometrik tervalidasi atau protokol klinis dari narasumber. Aplikasi tidak merekomendasikan obat, diet eliminasi universal, terapi klinis, atau diagnosis dari perilaku tunggal.</p><p>Rujukan tambahan: <a target="_blank" rel="noopener noreferrer" href="https://www.cdc.gov/adhd/diagnosis/index.html">CDC tentang proses diagnosis ADHD</a>; <a target="_blank" rel="noopener noreferrer" href="https://www.nimh.nih.gov/health/publications/children-and-mental-health">NIMH tentang evaluasi kesehatan mental anak</a>.</p>`)} </div>`}

function renderView(){switch(state.view){case 'students':return students();case 'child-form':return childForm();case 'observations':return observations();case 'observation-form':return obsForm();case 'signals':return signals();case 'supports':return supports();case 'plan-form':return planForm();case 'reports':return reports();case 'guides':return guides();default:return home()}}
function render(){root.innerHTML='<style>'+APP_CSS+'</style><div class="app-body">'+shell()+'</div><div id="toast" role="status" aria-live="polite" class="toast" hidden></div>';updateStatus();syncMobileNav();}
function go(view){if(!MENU.some(x=>x[0]===view)&&!['observation-form','plan-form','child-form'].includes(view))view='home';state.view=view;state.mobile=false;render();window.scrollTo({top:host.getBoundingClientRect().top+window.scrollY,behavior:'instant'});const h=root.querySelector('h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true})}formBaseline=readForm();}
function confirmAction(t){return window.confirm(t)}
function safeText(v){return String(v||'').trim()}
function onAction(ev){const target=ev.target.closest('[data-action]');if(!target)return;const a=target.dataset.action,id=target.dataset.id;
if(a==='toggle-menu'){state.mobile=!state.mobile;render();return}if(a==='close-menu'){state.mobile=false;render();return}
if(a==='navigate'){if(canLeave())go(target.dataset.target);return}
if(a==='new-child'){state.editingChild=null;go('child-form');return}if(a==='edit-child'){state.editingChild=id;go('child-form');return}
if(a==='delete-child'){const s=getStudent(id);if(!s)return;if(!confirmAction(`Hapus ${s.code} dan seluruh observasi serta dukungan demo yang berkaitan?`))return;data.students=data.students.filter(x=>x.id!==id);data.observations=data.observations.filter(x=>x.childId!==id);data.plans=data.plans.filter(x=>x.childId!==id);state.student=data.students[0]?.id||'';state.reportStudent=state.student;save();render();notify('Profil dan catatan terkait dihapus dari.');return}
if(a==='new-observation'){if(!data.students.length)return notify('Tambahkan profil anak terlebih dahulu.');state.editingObs=null;go('observation-form');return}if(a==='edit-observation'){state.editingObs=id;go('observation-form');return}
if(a==='delete-observation'){if(!confirmAction('Hapus catatan observasi ini?'))return;data.observations=data.observations.filter(x=>x.id!==id);data.plans.forEach(x=>{if(x.observationId===id)x.observationId=''});save();render();notify('Catatan observasi dihapus.');return}
if(a==='view-child'){state.student=id;state.signalsTab='summary';go('signals');return}if(a==='signal-tab'){state.signalsTab=id;render();return}
if(a==='new-plan'){if(!data.students.length)return notify('Tambahkan profil anak terlebih dahulu.');state.editingPlan=null;go('plan-form');return}if(a==='edit-plan'){state.editingPlan=id;go('plan-form');return}
if(a==='delete-plan'){if(!confirmAction('Hapus rencana pendampingan ini?'))return;data.plans=data.plans.filter(x=>x.id!==id);save();render();notify('Rencana dihapus.');return}
if(a==='clear'){if(!confirmAction('Kosongkan semua profil, observasi, dan rencana pada mode ini? Unduh cadangan dahulu bila diperlukan.'))return;data={students:[],observations:[],plans:[]};selectFirst();save();go('home');notify('Data dikosongkan. Cadangan lama tetap berisi data lama.');return}
if(a==='reset'){if(mode!=='demo')return;if(!confirmAction('Ganti seluruh perubahan latihan dengan data contoh?'))return;data=demo();selectFirst();go('home');return}
if(a==='print-report'){printReport();return}
if(a==='export-csv'){exportCsv();return}}
function onSubmit(ev){const form=ev.target;if(!['child-form','observation-form','plan-form'].includes(form.id))return;ev.preventDefault();if(!form.reportValidity())return;const f=new FormData(form);const get=k=>safeText(f.get(k));
if(form.id==='child-form'){
 const code=get('code').toUpperCase();const klass=get('klass');if(!klass)return notify('Kelas harus diisi.');if(!/^[A-Z0-9-]{3,24}$/.test(code))return notify('Kode hanya boleh huruf, angka, dan tanda hubung.');
 if(data.students.some(x=>x.code===code&&x.id!==state.editingChild))return notify('Kode sudah dipakai. Pilih kode lain.');
 if(state.editingChild){const x=data.students.find(x=>x.id===state.editingChild);if(!x)return;x.code=code;x.klass=klass;x.strength=get('strength')}
 else{const id=uid('CH');data.students.push({id,code,klass,strength:get('strength')});state.student=id;state.reportStudent=id}
 save();go('students');notify('Profil berhasil disimpan.');return}
if(form.id==='observation-form'){
 const childId=get('childId');if(!getStudent(childId)||!data.students.some(x=>x.id===childId))return notify('Profil anak tidak ditemukan.');
 const area=get('area'),indicator=get('indicator');if(!(area in AREAS)||!IND[indicator]||!indicator.startsWith(area))return notify('Area dan indikator belum sesuai.');
 if(!validDate(get('date'))||get('date')>iso())return notify('Tanggal observasi harus valid dan tidak melebihi hari ini.');
 const o={id:state.editingObs||uid('OBS'),childId,date:get('date'),area,indicator,context:get('context'),prior:get('prior'),behavior:get('behavior'),impact:get('impact'),response:get('response'),strength:get('strength'),occurrence:get('occurrence'),duration:get('duration'),author:get('author'),urgent:f.has('urgent')};
 if(!o.context||!o.prior||!o.behavior||!o.strength)return notify('Lengkapi konteks, perilaku faktual, dan kekuatan anak.');
 if(state.editingObs){const i=data.observations.findIndex(x=>x.id===state.editingObs);if(i===-1)return;data.observations[i]=o;data.plans.forEach(p=>{if(p.observationId===o.id&&p.childId!==o.childId)p.observationId=''})}else data.observations.push(o);
 state.student=childId;save();state.safetyShown=o.urgent;go('observations');notify(o.urgent?'Tersimpan. Utamakan SOP keselamatan anak, jangan menunggu skor.':'Observasi tersimpan dan Peta Sinyal diperbarui.');return}
if(form.id==='plan-form'){
 const childId=get('childId');if(!data.students.some(s=>s.id===childId))return notify('Kode anak tidak tersedia.');
 const observationId=get('observationId');if(observationId&&!(data.observations.some(o=>o.id===observationId&&o.childId===childId)))return notify('Rujukan observasi harus berasal dari kode anak yang sama.');
 if(!validDate(get('startDate'))||!validDate(get('reviewDate')))return notify('Tanggal rencana belum valid.');
 if(get('status')==='done'&&!get('result'))return notify('Catat hasil peninjauan sebelum menandai selesai.');
 if(get('reviewDate')<get('startDate'))return notify('Tanggal peninjauan tidak boleh sebelum tanggal mulai.');
 const p={id:state.editingPlan||uid('SUP'),childId,observationId,action:get('action'),owner:get('owner'),status:get('status'),startDate:get('startDate'),reviewDate:get('reviewDate'),result:get('result')};
 if(!p.action)return notify('Lengkapi tindakan pendampingan.');if(!(p.status in LABEL_STATUS))return notify('Status rencana tidak dikenal.');
 if(state.editingPlan){const i=data.plans.findIndex(x=>x.id===state.editingPlan);if(i===-1)return;data.plans[i]=p}else data.plans.push(p);
 state.student=childId;save();go('supports');notify('Rencana pendampingan berhasil disimpan.');return}}
function onChange(ev){if(ev.target.id==='plan-child'){const el=root.getElementById('plan-obs');el.innerHTML='<option value="">Tidak dipilih</option>'+data.observations.filter(o=>o.childId===ev.target.value).map(o=>'<option value="'+esc(o.id)+'">'+esc(o.id)+' · '+esc(IND[o.indicator])+'</option>').join('');return}
if(ev.target.id==='obs-area'){const area=ev.target.value;const el=root.getElementById('obs-indicator');if(el)el.innerHTML=indicators(area);return}
if(ev.target.id==='signal-child'){state.student=ev.target.value;state.signalsTab='summary';render();return}
if(ev.target.id==='report-child'){state.reportStudent=ev.target.value;render();return}
if(ev.target.id==='obs-filter'){state.obsFilter=ev.target.value;render();return}}
function onInput(ev){if(ev.target.id==='child-search'){state.studentFilter=ev.target.value;const input=ev.target;const cursor=input.selectionStart;render();const next=root.getElementById('child-search');if(next){next.focus();next.setSelectionRange(cursor,cursor)}}}
function exportCsv(){const rows=[['kelompok','jumlah_catatan','keterangan'],...countsByArea(data.observations).map(x=>[AREAS[x.key].name,x.count,mode==='demo'?'SIMULASI; bukan skor psikologis':'Catatan lokal; bukan skor psikologis'])];const csv='\ufeff'+rows.map(r=>r.map(escapeCsv).join(';')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='EDUMIND_REKAP_AGREGAT_'+mode+'_' +iso()+'.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('CSV rekap agregat data dibuat.');}
// Local vault. No child records, passwords, or keys are transmitted by this code.
let mode='locked', key=null, salt=null, diskRaw=null, pending=Promise.resolve(), saving=0, saveError='', savedAt='', idleTimer, formBaseline='', authBusy=false, operationBusy=false, cancelPassword=null, recoveryRaw=null, accessPassword='', activeAccountHash='', parkedSession=null, restoreLogin=null;
const LIMIT=5*1024*1024, ITERATIONS=310000;
const enc=new TextEncoder(),dec=new TextDecoder('utf-8',{fatal:true});
function validDate(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s))return false;const d=new Date(s+'T12:00:00Z');return !isNaN(d)&&d.toISOString().slice(0,10)===s&&s>='1900-01-01'&&s<='2200-12-31'}
function validateData(obj){
 if(!obj||typeof obj!=='object'||!Array.isArray(obj.students)||!Array.isArray(obj.observations)||!Array.isArray(obj.plans))throw Error('Struktur data tidak sesuai.');
 if(obj.students.length>2000||obj.observations.length>15000||obj.plans.length>10000)throw Error('Jumlah rekaman melebihi batas perangkat.');
 const text=(o,k,max,required=false)=>{const v=o[k];if(typeof v!=='string'||v.length>max||(required&&!v.trim())||/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(v))throw Error('Data tidak valid pada '+k+'.');return v.trim()};
 const ids=new Set(),codes=new Set();const checkId=o=>{const id=text(o,'id',100,true);if(!/^[A-Za-z0-9-]+$/.test(id)||ids.has(id))throw Error('ID tidak valid atau ganda.');ids.add(id);return id};
 const students=obj.students.map(o=>{const id=checkId(o),code=text(o,'code',24,true).toUpperCase();if(!/^[A-Z0-9-]{3,24}$/.test(code)||codes.has(code))throw Error('Kode anak tidak valid atau ganda.');codes.add(code);return{id,code,klass:text(o,'klass',24,true),strength:text(o,'strength',500)}});
 const children=new Set(students.map(x=>x.id));
 const childId=o=>{const v=text(o,'childId',100,true);if(!children.has(v))throw Error('Catatan tidak memiliki profil anak.');return v};
 const date=(o,k)=>{const d=text(o,k,10,true);if(!validDate(d))throw Error('Tanggal tidak valid.');return d};
 const observations=obj.observations.map(o=>{const id=checkId(o),ch=childId(o),area=text(o,'area',2,true),indicator=text(o,'indicator',4,true);if(!Object.hasOwn(AREAS,area)||!Object.hasOwn(IND,indicator)||!indicator.startsWith(area)||typeof o.urgent!=='boolean')throw Error('Indikator atau penanda tidak valid.');const d=date(o,'date');if(d>iso())throw Error('Tanggal observasi di masa depan.');return{id,childId:ch,date:d,area,indicator,context:text(o,'context',180,true),prior:text(o,'prior',1500,true),behavior:text(o,'behavior',1500,true),impact:text(o,'impact',800),response:text(o,'response',1000),strength:text(o,'strength',900,true),occurrence:text(o,'occurrence',100),duration:text(o,'duration',80),author:text(o,'author',80,true),urgent:o.urgent}});
 const obs=new Map(observations.map(o=>[o.id,o]));
 const plans=obj.plans.map(o=>{const id=checkId(o),ch=childId(o),observationId=text(o,'observationId',100),status=text(o,'status',20,true),startDate=date(o,'startDate'),reviewDate=date(o,'reviewDate'),result=text(o,'result',1500);if(!Object.hasOwn(LABEL_STATUS,status)||reviewDate<startDate||(status==='done'&&!result)||(observationId&&obs.get(observationId)?.childId!==ch))throw Error('Rencana atau tautan observasi tidak valid.');return{id,childId:ch,observationId,status,startDate,reviewDate,result,action:text(o,'action',1500,true),owner:text(o,'owner',100,true)}});
 return {students,observations,plans};
}
function b64(bytes){let str='';for(let i=0;i<bytes.length;i+=8192)str+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(str)}
function passwordDialog(title,confirmNew=false){return new Promise(resolve=>{const overlay=document.createElement('div');overlay.className='password-overlay';overlay.innerHTML=`<section class="password-panel" role="dialog" aria-modal="true" aria-labelledby="password-title"><h2 id="password-title">${esc(title)}</h2><form id="password-dialog"><div class="field"><label for="dialog-password">Frasa sandi${confirmNew?' baru':''}</label><input id="dialog-password" type="password" name="password" required minlength="${confirmNew?12:1}" maxlength="256" autocomplete="${confirmNew?'new-password':'current-password'}"></div>${confirmNew?'<div class="field"><label for="dialog-confirm">Ulangi frasa sandi baru</label><input id="dialog-confirm" type="password" name="confirm" required minlength="12" maxlength="256" autocomplete="new-password"></div>':''}<p class="error" role="alert" id="password-error"></p><div class="form-footer"><button class="btn" type="button" id="password-cancel">Batal</button><button class="btn primary" type="submit">Lanjutkan</button></div></form></section>`;const focused=root.activeElement,body=root.querySelector('.app-body');if(body)body.inert=true;const done=value=>{overlay.remove();if(body)body.inert=false;cancelPassword=null;focused?.focus();resolve(value)};cancelPassword=()=>done(null);overlay.querySelector('#password-cancel').onclick=()=>done(null);overlay.querySelector('form').onsubmit=ev=>{ev.preventDefault();ev.stopPropagation();const f=ev.target;if(!f.reportValidity())return;const fd=new FormData(f),password=fd.get('password');if(confirmNew&&password!==fd.get('confirm')){overlay.querySelector('#password-error').textContent='Kedua frasa sandi harus sama.';return}f.reset();done(password)};overlay.addEventListener('keydown',ev=>{if(ev.key==='Escape'){ev.stopPropagation();done(null)}if(ev.key==='Tab'){const nodes=[...overlay.querySelectorAll('input,button')];const first=nodes[0],last=nodes.at(-1);if(ev.shiftKey&&root.activeElement===first){ev.preventDefault();last.focus()}else if(!ev.shiftKey&&root.activeElement===last){ev.preventDefault();first.focus()}}});root.appendChild(overlay);overlay.querySelector('input').focus()})}
function unb64(s){if(typeof s!=='string'||s.length>LIMIT*2||!/^[A-Za-z0-9+/]*={0,2}$/.test(s))throw Error('Format enkripsi tidak valid.');return Uint8Array.from(atob(s),c=>c.charCodeAt(0))}
function parseEnvelope(raw){if(typeof raw!=='string'||raw.length>LIMIT)throw Error('Ukuran cadangan melebihi 5 MB.');const o=JSON.parse(raw);if(o.format!=='EDUMIND-PSPA'||o.version!==1||o.kdf!=='PBKDF2-SHA256'||o.iterations!==ITERATIONS||o.cipher!=='AES-GCM'||unb64(o.salt).length!==16||unb64(o.iv).length!==12||unb64(o.data).length<16)throw Error('Format cadangan tidak didukung.');return o}
async function derive(password,saltBytes){const material=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt:saltBytes,iterations:ITERATIONS,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
function cryptoAAD(envelope){return enc.encode(envelope.access==='edumind-personal-v1'?'EDUMIND-PSPA-v1|personal|'+envelope.accountHash:'EDUMIND-PSPA-v1')}
async function encryptData(obj,k=key,st=salt,account=activeAccountHash){const iv=crypto.getRandomValues(new Uint8Array(12)),header=APP_VARIANT==='personal'?{access:'edumind-personal-v1',accountHash:account}:{access:'edumind-standard-v1'};if(APP_VARIANT==='personal'&&unb64(account).length!==32)throw Error('Akun lokal belum sesuai.');const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:cryptoAAD(header)},k,enc.encode(JSON.stringify(validateData(obj))));const raw=JSON.stringify({format:'EDUMIND-PSPA',version:1,kdf:'PBKDF2-SHA256',iterations:ITERATIONS,cipher:'AES-GCM',...header,salt:b64(st),iv:b64(iv),data:b64(new Uint8Array(cipher))});if(raw.length>LIMIT)throw Error('Data melebihi kapasitas 5 MB. Unduh cadangan lalu arsipkan data yang tidak diperlukan.');return raw}
async function decryptWithKey(raw,k){const env=parseEnvelope(raw),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(env.iv),additionalData:cryptoAAD(env)},k,unb64(env.data));return validateData(JSON.parse(dec.decode(plain)))}
async function decryptData(raw,password){const env=parseEnvelope(raw),st=unb64(env.salt),k=await derive(password,st);return{data:await decryptWithKey(raw,k),key:k,salt:st}}
async function writeDisk(raw,expected){const write=()=>{if(localStorage.getItem(STORAGE)!==expected)throw Error('Data berubah pada tab lain. Kunci dan buka ulang, atau unduh cadangan perubahan tab ini.');localStorage.setItem(STORAGE,raw);if(localStorage.getItem(STORAGE)!==raw)throw Error('Penyimpanan tidak dapat diverifikasi.');diskRaw=raw};if(navigator.locks)await navigator.locks.request(STORAGE,{mode:'exclusive'},write);else write()}
function updateStatus(){const el=root.getElementById('storage-state');if(!el)return;el.className='storage-state'+(saveError?' failed':'');el.textContent=mode==='demo'?'Latihan hanya di memori halaman; tidak mengubah data lokal terenkripsi.':saveError?'BELUM TERSIMPAN: '+saveError+' Unduh cadangan sebelum menutup halaman.':saving?'Mengenkripsi dan menyimpan perubahan…':savedAt?'Tersimpan terenkripsi di browser ini · '+savedAt:'Data lokal terbuka. Unduh cadangan setelah bekerja.'}
function save(){if(mode!=='live')return Promise.resolve(true);const snapshot=JSON.parse(JSON.stringify(data));saving++;updateStatus();pending=pending.then(async()=>{try{const raw=await encryptData(snapshot);await writeDisk(raw,diskRaw);saveError='';savedAt=new Date().toLocaleTimeString('id-ID');return true}catch(e){saveError=e.message||'Penyimpanan gagal.';return false}finally{saving--;updateStatus()}});return pending}
