function setAuthError(message){const el=root.getElementById('auth-error');if(el){el.textContent=message;el.hidden=!message}else notify(message)}
async function accountHash(username){return b64(new Uint8Array(await crypto.subtle.digest('SHA-256',enc.encode(username.trim().toLowerCase()))))}
async function openVault(ev){
 ev.preventDefault();if(authBusy||operationBusy)return;const f=ev.target;if(!f.reportValidity())return;
 const fd=new FormData(f),username=fd.get('username').trim().toLowerCase(),password=fd.get('password');let raw=null;
 if(!/^[a-z0-9._-]{3,40}$/.test(username))return setAuthError('Username belum sesuai.');
 authBusy=true;const submit=f.querySelector('[type=submit]');submit.disabled=true;
 try{
  raw=localStorage.getItem(STORAGE);const hash=await accountHash(username);let result;
  if(raw){const envelope=parseEnvelope(raw);if(envelope.access!=='edumind-personal-v1'||envelope.accountHash!==hash)throw Error('Username atau password tidak sesuai, atau data lokal tidak dapat dibaca.');try{result=await decryptData(raw,password)}catch(e){throw Error('Username atau password tidak sesuai, atau data lokal tidak dapat dibaca.')}diskRaw=raw}
  else{if(password.length<12||password!==fd.get('confirm'))throw Error('Password minimal 12 karakter dan konfirmasi harus sama.');activeAccountHash=hash;const nextSalt=crypto.getRandomValues(new Uint8Array(16)),nextKey=await derive(password,nextSalt),empty={students:[],observations:[],plans:[]};await writeDisk(await encryptData(empty,nextKey,nextSalt),null);result={data:empty,key:nextKey,salt:nextSalt}}
  activeAccountHash=hash;accessPassword=password;key=result.key;salt=result.salt;data=result.data;saveError='';savedAt='';f.reset();mode='live';selectFirst();go('home');touch();
 }catch(e){key=null;salt=null;activeAccountHash='';accessPassword='';data={students:[],observations:[],plans:[]};setAuthError(e.message||'Data belum dapat dibuka. Data tersimpan tidak diubah.')}
 finally{authBusy=false;if(submit.isConnected)submit.disabled=false}
}
function beginPersonalRestore(){const form=root.getElementById('vault-form');const username=form.elements.username.value.trim().toLowerCase(),password=form.elements.password.value;if(!/^[a-z0-9._-]{3,40}$/.test(username)||password.length<12){setAuthError('Isi username dan password cadangan pribadi terlebih dahulu. Password minimal 12 karakter.');return}restoreLogin={username,password};let input=root.getElementById('restore-file');if(!input){input=document.createElement('input');input.id='restore-file';input.type='file';input.accept='.edumind,application/json';input.hidden=true;input.addEventListener('cancel',()=>{restoreLogin=null});root.appendChild(input)}input.value='';input.click()}
async function restoreFile(file){
 const locked=mode==='locked',login=locked?{username:root.getElementById('vault-username')?.value.trim().toLowerCase(),password:root.getElementById('vault-password')?.value}:null;restoreLogin=null;if(!file)return;if(file.size>LIMIT)return notify('Cadangan melebihi 5 MB.');if(locked&&(!login.username||!login.password))return;
 try{
  const raw=await file.text(),env=parseEnvelope(raw);let result,nextAccountHash=activeAccountHash,nextPassword=accessPassword;
  if(locked){nextAccountHash=await accountHash(login.username);nextPassword=login.password;if(env.access!=='edumind-personal-v1'||env.accountHash!==nextAccountHash)throw Error('Akun cadangan tidak sesuai.');result=await decryptData(raw,nextPassword)}
  else{try{result=await decryptData(raw,accessPassword)}catch(e){const previous=await passwordDialog('Password untuk membuka cadangan');if(previous===null)return;result=await decryptData(raw,previous)}}
  await pending;if(!locked&&!canLeave())return;
  if(!confirmAction('Pemulihan mengganti SELURUH data versi pribadi pada browser ini. Unduh cadangan data saat ini terlebih dahulu bila diperlukan. Lanjutkan?'))return;
  const current=localStorage.getItem(STORAGE);if(!locked&&current!==diskRaw)throw Error('Data berubah pada tab lain.');
  const nextSalt=crypto.getRandomValues(new Uint8Array(16)),nextKey=await derive(nextPassword,nextSalt);
  await writeDisk(await encryptData(result.data,nextKey,nextSalt,nextAccountHash),current);data=result.data;key=nextKey;salt=nextSalt;activeAccountHash=nextAccountHash;accessPassword=nextPassword;saveError='';savedAt='Dipulihkan';mode='live';selectFirst();go('home');touch();notify('Cadangan dipulihkan ke akun lokal pribadi.');
 }catch(e){notify('Pemulihan gagal: akun/password cadangan tidak sesuai, data rusak, atau penyimpanan gagal. Data sebelumnya tetap dipertahankan.')}
}
async function changePassword(){await pending;if(saveError)return notify('Selesaikan penyimpanan atau unduh cadangan dahulu.');const current=await passwordDialog('Konfirmasi password saat ini');if(current===null)return;try{await decryptData(diskRaw,current)}catch(e){return notify('Password saat ini tidak sesuai.')}const password=await passwordDialog('Buat password pribadi baru',true);if(password===null)return;try{const nextSalt=crypto.getRandomValues(new Uint8Array(16)),nextKey=await derive(password,nextSalt);await writeDisk(await encryptData(data,nextKey,nextSalt),diskRaw);key=nextKey;salt=nextSalt;accessPassword=password;savedAt='Password diperbarui';updateStatus();notify('Password diperbarui. Buat cadangan baru; cadangan lama tetap memakai password lamanya.')}catch(e){notify('Perubahan password gagal. Data sebelumnya tetap dipertahankan.')}}

function printReport(){const report=root.getElementById('report-paper');if(!report)return;const frame=document.createElement('iframe');frame.title='Cetak laporan observasi';frame.style.cssText='position:fixed;left:-10000px;top:0;width:900px;height:1px';document.body.appendChild(frame);const doc=frame.contentDocument;doc.open();doc.write('<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Laporan Observasi Pendidikan</title><style>body{font:11pt/1.5 Arial;color:#000}h3{margin:18px 0 8px}table{width:100%;border-collapse:collapse;font-size:9pt}td,th{border:1px solid #bbb;padding:7px;vertical-align:top;overflow-wrap:anywhere}th{text-align:left;background:#eee}thead{display:table-header-group}td:first-child{white-space:nowrap}p{white-space:pre-wrap}.report-title{font-size:19pt;font-weight:bold}.report-grid{display:flex;gap:25px;margin:15px 0}.report-grid b{display:block}.tiny{font-size:9pt}.report-legal{margin-top:18px;padding:10px;border:1px solid #777}tr{break-inside:avoid}@page{size:A4;margin:14mm}</style></head><body>'+report.outerHTML+'</body></html>');doc.close();frame.contentWindow.addEventListener('afterprint',()=>frame.remove(),{once:true});frame.contentWindow.focus();frame.contentWindow.print();setTimeout(()=>frame.remove(),120000)}
root.addEventListener('click',async ev=>{touch();const el=ev.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(authBusy||operationBusy)return;if(action==='recovery-backup'){download(recoveryRaw,'EDUMIND_PSPA_PEMULIHAN_SESI_'+iso()+'.edumind');return}if(action==='copy-local-vault'){download(diskRaw,'EDUMIND_PSPA_SALINAN_LOKAL_'+iso()+'.edumind');return}if(action==='toggle-password'){const input=root.getElementById('vault-password'),show=input.type==='password';input.type=show?'text':'password';el.setAttribute('aria-pressed',String(show));el.setAttribute('aria-label',show?'Sembunyikan password':'Tampilkan password');el.querySelector('span').textContent=show?'Sembunyikan':'Lihat';return}if(action==='start-demo'){authBusy=true;try{await enterDemo()}finally{authBusy=false}return}if(action==='return-live'){authBusy=true;try{await returnToLive()}finally{authBusy=false}return}if(action==='auth-restore'&&APP_VARIANT==='personal'){beginPersonalRestore();return}if(action==='export-excel'){await exclusive(exportExcel);return}if(action==='change-password'&&APP_VARIANT==='personal'&&mode==='live'){await exclusive(changePassword);return}if(action==='lock'){await lockApp();return}if(action==='backup'){await exclusive(backup);return}if(action==='restore'&&mode==='live'){let input=root.getElementById('restore-file');if(!input){input=document.createElement('input');input.id='restore-file';input.type='file';input.accept='.edumind,application/json';input.hidden=true;root.appendChild(input)}input.value='';input.click();return}if(mode!=='locked')onAction(ev)});
root.addEventListener('submit',ev=>{touch();if(ev.target.id==='vault-form'){openVault(ev);return}if(operationBusy){ev.preventDefault();return}if(mode!=='locked')onSubmit(ev)});
root.addEventListener('change',ev=>{touch();if(ev.target.id==='restore-file'){exclusive(()=>restoreFile(ev.target.files[0]));return}if(mode!=='locked')onChange(ev)});
root.addEventListener('input',ev=>{touch();if(mode!=='locked')onInput(ev)});
root.addEventListener('keydown',ev=>{touch();if(ev.key==='Escape'&&state.mobile){state.mobile=false;render();root.querySelector('.mobile-menu')?.focus()}});
root.addEventListener('pointerdown',touch);
