window.addEventListener('storage',ev=>{if(mode==='live'&&ev.key===STORAGE&&ev.newValue!==diskRaw){saveError='Data berubah pada tab lain. Unduh cadangan perubahan tab ini, lalu kunci dan buka ulang.';updateStatus()}});
