async function enterDemo(){
 if(mode==='demo')return;if(mode==='live'&&!canLeave())return;await pending;
 if(mode==='live'&&saveError)return notify('Unduh cadangan dan selesaikan penyimpanan dahulu.');
 parkedSession=mode==='live'&&key?{key,salt,diskRaw,accessPassword,activeAccountHash}:null;
 key=null;salt=null;accessPassword='';activeAccountHash='';restoreLogin=null;
 data=demo();mode='demo';selectFirst();go('home');touch();notify('Data simulasi dibuka terpisah. Data kerja tidak diubah.');
}
async function returnToLive(){
 if(!canLeave())return;if(!parkedSession){await lockApp();return}
 try{const raw=localStorage.getItem(STORAGE);if(!raw)throw Error('Penyimpanan data kerja tidak tersedia.');const restored=await decryptWithKey(raw,parkedSession.key);key=parkedSession.key;salt=parkedSession.salt;accessPassword=parkedSession.accessPassword;activeAccountHash=parkedSession.activeAccountHash;diskRaw=raw;data=restored;parkedSession=null;mode='live';saveError='';selectFirst();go('home');touch();notify('Kembali ke data kerja. Perubahan simulasi tidak digabungkan.')}catch(e){parkedSession=null;await lockApp();setAuthError('Data kerja berubah atau belum dapat dibuka. Silakan login kembali.')}
}
function workspaceSwitch(){return mode==='demo'?`<section class="workspace-switch simulation"><div><strong>MODE SIMULASI — SELURUH DATA FIKTIF</strong><p>Latihan di sini tidak mengubah data kerja Anda.</p></div>${btn(parkedSession?'Kembali ke Data Kerja':'Kembali ke Halaman Masuk','return-live','btn primary')}</section>`:`<section class="workspace-switch"><div><strong>Ruang Data Kerja</strong><p>Contoh latihan tersedia terpisah untuk membantu Anda mulai.</p></div>${btn('Coba Data Simulasi','start-demo','btn primary')}</section>`}

