function exportsPanel(){return card(`<h3>Unduh Data Seluruh Anak</h3><p>Ekspor seluruh profil, observasi, rencana, hasil pendampingan, dan rekap area ke Excel. Pilihan anak pada laporan cetak tidak membatasi ekspor ini.</p><div class="title-actions">${btn('Unduh Excel Seluruh Data','export-excel','btn primary')}${mode==='live'?btn('Cadangkan untuk Pemulihan','backup','btn'):''}</div><p class="export-note">Excel untuk dibaca dan diolah, tanpa enkripsi. Pulihkan aplikasi menggunakan berkas cadangan terenkripsi .edumind. Mode simulasi hanya mengekspor contoh fiktif.</p>`,'exports-panel')}
function excelXml(value){return String(value??'').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g,'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]))}
function excelCol(n){let s='';for(;n>0;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s}
function zipStore(parts){
 const table=new Uint32Array(256);for(let i=0;i<256;i++){let c=i;for(let j=0;j<8;j++)c=c&1?0xedb88320^(c>>>1):c>>>1;table[i]=c>>>0}
 const crc=bytes=>{let c=0xffffffff;for(const b of bytes)c=table[(c^b)&255]^(c>>>8);return (c^0xffffffff)>>>0};
 const chunks=[],central=[];let offset=0,centralSize=0;const put=(view,at,value,size)=>size===2?view.setUint16(at,value,true):view.setUint32(at,value,true);
 for(const [path,text] of parts){const name=enc.encode(path),body=enc.encode(text),sum=crc(body),head=new Uint8Array(30+name.length),v=new DataView(head.buffer);put(v,0,0x04034b50,4);put(v,4,20,2);put(v,6,0x800,2);put(v,10,0,2);put(v,12,33,2);put(v,14,sum,4);put(v,18,body.length,4);put(v,22,body.length,4);put(v,26,name.length,2);head.set(name,30);chunks.push(head,body);
  const entry=new Uint8Array(46+name.length),e=new DataView(entry.buffer);put(e,0,0x02014b50,4);put(e,4,20,2);put(e,6,20,2);put(e,8,0x800,2);put(e,12,0,2);put(e,14,33,2);put(e,16,sum,4);put(e,20,body.length,4);put(e,24,body.length,4);put(e,28,name.length,2);put(e,42,offset,4);entry.set(name,46);central.push(entry);centralSize+=entry.length;offset+=head.length+body.length;
 }
 const end=new Uint8Array(22),v=new DataView(end.buffer);put(v,0,0x06054b50,4);put(v,8,parts.length,2);put(v,10,parts.length,2);put(v,12,centralSize,4);put(v,16,offset,4);return new Blob([...chunks,...central,end],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
}
function excelSheet(sheet,stamp){
 const last=excelCol(sheet.headers.length),maxRow=5+sheet.rows.length;
 const cell=(value,row,col,style=0)=>typeof value==='number'&&Number.isFinite(value)?`<c r="${excelCol(col)}${row}" s="3" t="n"><v>${value}</v></c>`:`<c r="${excelCol(col)}${row}" s="${style}" t="inlineStr"><is><t xml:space="preserve">${excelXml(value)}</t></is></c>`;
 const notice=mode==='demo'?'SIMULASI FIKTIF — Bukan diagnosis. Contoh latihan.':'DATA TERBATAS — Bukan diagnosis. Salinan Excel tidak terenkripsi; bagikan hanya kepada pihak berwenang.';
 const rows=[`<row r="1" ht="30" customHeight="1">${cell(sheet.title,1,1,2)}</row>`,`<row r="2" ht="42" customHeight="1">${cell(notice,2,1,4)}</row>`,`<row r="3" ht="25" customHeight="1">${cell('Edumind Academy · '+VERSION+' · '+stamp+' · '+(APP_VARIANT==='personal'?'Akun pribadi':'Akun siap pakai')+' · Excel untuk dibaca; pulihkan aplikasi dengan cadangan .edumind.',3,1,4)}</row>`,`<row r="5" ht="34" customHeight="1">${sheet.headers.map((h,i)=>cell(h,5,i+1,1)).join('')}</row>`,...sheet.rows.map((r,i)=>`<row r="${i+6}">${r.map((value,j)=>cell(value,i+6,j+1)).join('')}</row>`)];
 return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetPr><pageSetUpPr fitToPage="1"/></sheetPr><dimension ref="A1:${last}${maxRow}"/><sheetViews><sheetView showGridLines="0" workbookViewId="0"><pane ySplit="5" topLeftCell="A6" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight="20"/><cols>${sheet.widths.map((w,i)=>`<col min="${i+1}" max="${i+1}" width="${w}" customWidth="1"/>`).join('')}</cols><sheetData>${rows.join('')}</sheetData><autoFilter ref="A5:${last}${maxRow}"/><mergeCells count="3">${[1,2,3].map(r=>`<mergeCell ref="A${r}:${last}${r}"/>`).join('')}</mergeCells><pageMargins left="0.3" right="0.3" top="0.4" bottom="0.4" header="0.2" footer="0.2"/><pageSetup paperSize="9" orientation="landscape" fitToWidth="1" fitToHeight="0"/></worksheet>`;
}
